def build_vocab_card(word, definition, example):
    escaped_word = word.replace("'", "\\'")
    escaped_def = definition.replace("'", "\\'")
    escaped_ex = example.replace("'", "\\'")
    return f'''<div class="vocab-card"><div class="vocab-word" style="font-size: 1.1rem; font-weight: bold; color: var(--indigo); margin-bottom: 0.25rem;">{word}</div>
<div class="vocab-def">{definition}</div>
<div class="vocab-example">{example}</div>
<button class="btn-add-dict" onclick="COSY.addToDict({{word:'{escaped_word}', definition:'{escaped_def}', example:'{escaped_ex}'}}, this)">+ Dictionary</button>
</div>'''

def build_round1_item(main_q, personal_q):
    return f'''<div class="round-item"><div class="round-item-main">{main_q}</div>
<div class="round-item-personal">{personal_q}</div>
</div>'''

def build_round2_item(main_q):
    return f'''<div class="round-item"><div class="round-item-main">{main_q}</div>
</div>'''

def build_lang_focus(title, desc, examples):
    ex_lis = "".join([f'<li style="margin-bottom: 0.5rem; font-size: 0.9rem;">{ex}</li>' for ex in examples])
    return f'''<div style="background: var(--cream); border-left: 4px solid var(--indigo); padding: 1.5rem; border-radius: 0 16px 16px 0; margin-bottom: 1.5rem;">
      <h3 style="margin-top: 0; font-family: 'Playfair Display', serif; font-size: 1.2rem; color: var(--indigo);">{title}</h3>
      <p style="font-size: 0.92rem; line-height: 1.6; color: var(--ink-soft); margin-bottom: 1rem;">{desc}</p>
      <strong style="font-size: 0.85rem; text-transform: uppercase; color: var(--muted); letter-spacing: 0.05em; display: block; margin-bottom: 0.5rem;">Давайте попрактикуемся - 3 примера:</strong>
      <ul style="margin: 0; padding-left: 1.2rem; color: var(--indigo);">
        {ex_lis}
      </ul>
    </div>'''

def build_mistakes(mistakes):
    items = []
    for wrong, right, note in mistakes:
        items.append(f'''<div class="mistake-item">
            <span class="mistake-wrong">{wrong}</span>
            <span class="mistake-arrow">→</span>
            <span class="mistake-right">{right}</span>
            <span class="mistake-note-text">{note}</span>
          </div>''')
    return "\n".join(items)

