def remediate_file(key, info):
    filepath = info["filepath"]
    print(f"Remediating {filepath}...")
    with open(filepath, "r", encoding="utf-8") as f:
        content = f.read()

    soup = BeautifulSoup(content, "html.parser")
    options = soup.find_all("vim-choice-option")

    for opt in options:
        title_el = opt.find("vim-choice-option-title")
        if not title_el:
            continue
        song_title = title_el.get_text().strip()
        if song_title not in info["songs"]:
            print(f"Warning: {song_title} not found in DATA for {key}")
            continue

        song_data = info["songs"][song_title]

        # 1. Update Vocabulary
        vocab_grid = opt.find("div", class_="vocab-grid-10")
        if vocab_grid:
            vocab_grid.clear()
            h3_1 = soup.new_tag("h3")
            h3_1["style"] = "grid-column: 1 / -1; margin-top: 1rem; margin-bottom: 0.5rem; font-family:'Playfair Display', serif; font-size:1.1rem; color:var(--indigo);"
            h3_1.string = "❤️ Ключевые понятия и чувства"
            vocab_grid.append(h3_1)

            for word, defn, ex in song_data["vocab"][:5]:
                card_html = build_vocab_card(word, defn, ex)
                vocab_grid.append(BeautifulSoup(card_html, "html.parser"))

            h3_2 = soup.new_tag("h3")
            h3_2["style"] = "grid-column: 1 / -1; margin-top: 1rem; margin-bottom: 0.5rem; font-family:'Playfair Display', serif; font-size:1.1rem; color:var(--indigo);"
            h3_2.string = "🗣️ Жизнь, действия и связи"
            vocab_grid.append(h3_2)

            for word, defn, ex in song_data["vocab"][5:]:
                card_html = build_vocab_card(word, defn, ex)
                vocab_grid.append(BeautifulSoup(card_html, "html.parser"))
        else:
            print(f"Error: vocab-grid-10 not found for {song_title}")

        # 2. Update Discussion Round 1 & Round 2
        round1_div = opt.find("div", class_="round-1")
        if round1_div:
            round1_div.clear()
            h3_r1 = soup.new_tag("h3")
            h3_r1["style"] = "font-family:'Playfair Display', serif; font-size:1.1rem; color:var(--indigo); margin-bottom: 1rem;"
            h3_r1.string = "🔵 Round 1 - Lyric Analysis & Discussion"
            round1_div.append(h3_r1)
            for mq, pq in song_data["r1"]:
                r1_html = build_round1_item(mq, pq)
                round1_div.append(BeautifulSoup(r1_html, "html.parser"))
        else:
            print(f"Error: round-1 not found for {song_title}")

        round2_div = opt.find("div", class_="round-2")
        if round2_div:
            round2_div.clear()
            h3_r2 = soup.new_tag("h3")
            h3_r2["style"] = "font-family:'Playfair Display', serif; font-size:1.1rem; color:var(--indigo); margin-bottom: 1rem;"
            h3_r2.string = "🟢 Round 2 - Broad Themes & Philosophy Debate"
            round2_div.append(h3_r2)
            for mq in song_data["r2"]:
                r2_html = build_round2_item(mq)
                round2_div.append(BeautifulSoup(r2_html, "html.parser"))
        else:
            print(f"Error: round-2 not found for {song_title}")

        # 3. Update Language Focus
        lang_focus_block = opt.find("div", id=lambda x: x and x.startswith("lang-focus-"))
        if lang_focus_block:
            body = lang_focus_block.find("div", class_="round-body")
            if body:
                body.clear()
                lf_html = build_lang_focus(song_data["lang_title"], song_data["lang_desc"], song_data["lang_examples"])
                body.append(BeautifulSoup(lf_html, "html.parser"))
        else:
            print(f"Error: lang-focus block not found for {song_title}")

        # 4. Update Teacher's Note
        mistake_block = opt.find("div", class_="mistake-block")
        if mistake_block:
            m_body = mistake_block.find("div", class_="mistake-body")
            if m_body:
                m_body.clear()
                m_html = build_mistakes(song_data["mistakes"])
                m_body.append(BeautifulSoup(m_html, "html.parser"))
        else:
            print(f"Error: mistake block not found for {song_title}")

    # Write back formatted HTML
    output_html = str(soup)
    with open(filepath, "w", encoding="utf-8") as f:
        f.write(output_html)
    print(f"Successfully remediated {filepath}")

for k, v in DATA.items():
    remediate_file(k, v)

print("All 4 challenge files remediated successfully!")
